function solve(matrix) {
  const rows = matrix.length;
  if (!rows) return 0;
  const cols = matrix[0].length;
  const dp = new Array(cols + 1).fill(0);
  let best = 0;
  for (let i = 1; i <= rows; i++) {
    let prev = 0;
    for (let j = 1; j <= cols; j++) {
      const cur = dp[j];
      if (matrix[i - 1][j - 1] === '1') {
        dp[j] = Math.min(dp[j], dp[j - 1], prev) + 1;
        best = Math.max(best, dp[j]);
      } else {
        dp[j] = 0;
      }
      prev = cur;
    }
  }
  return best * best;
}
